import { createFileRoute } from '@tanstack/react-router'
import { useEffect, useMemo, useRef, useState } from 'react'
import { AppShell } from '../components/AppShell'
import { Icon } from '../components/Icons'
import { PromptCard } from '../components/PromptCard'
import { PromptModal } from '../components/PromptModal'
import { Toast } from '../components/Toast'
import type { CatalogData, Prompt } from '../lib/types'
import { getCatalogData } from '../server/marketplace.server'

export const Route = createFileRoute('/')({
  loader: () => getCatalogData({ data: {} }),
  component: Storefront,
})

const models = ['all','GPT-4o','Claude','Midjourney','Flux']
const sorts = ['featured','newest','popular'] as const

function Storefront() {
  const initial = Route.useLoaderData()
  const [catalog, setCatalog] = useState<CatalogData>(initial)
  const [model, setModel] = useState('all')
  const [category, setCategory] = useState('all')
  const [sort, setSort] = useState<typeof sorts[number]>('featured')
  const [term, setTerm] = useState('')
  const [favorites, setFavorites] = useState(false)
  const [free, setFree] = useState(false)
  const [searchOpen, setSearchOpen] = useState(false)
  const [preview, setPreview] = useState<Prompt | null>(null)
  const [notice, setNotice] = useState('')
  const [loading, setLoading] = useState(false)
  const searchRef = useRef<HTMLInputElement>(null)

  const toast = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 2200) }
  const revealSearch = () => { setSearchOpen(true); window.setTimeout(() => searchRef.current?.focus(), 50) }
  const chooseCategory = (value: string) => {
    if (value === '__free') { setFree(true); setFavorites(false); setCategory('all'); toast('Showing free prompts') }
    else { setCategory(value === category ? 'all' : value); setFree(false); setFavorites(false) }
  }

  useEffect(() => {
    const controller = new AbortController()
    const timeout = window.setTimeout(async () => {
      setLoading(true)
      const params = new URLSearchParams({ model, category, sort })
      if (term) params.set('q', term)
      if (favorites) params.set('favorites', 'true')
      if (free) params.set('free', 'true')
      try {
        const response = await fetch(`/api/prompts?${params}`, { signal: controller.signal })
        if (response.ok) setCatalog(await response.json())
      } finally { if (!controller.signal.aborted) setLoading(false) }
    }, term ? 180 : 0)
    return () => { window.clearTimeout(timeout); controller.abort() }
  }, [model, category, sort, term, favorites, free])

  const favoritePrompt = async (prompt: Prompt) => {
    const next = !prompt.isFavorite
    setCatalog((data) => ({ ...data, prompts: data.prompts.map((p) => p.id === prompt.id ? {...p,isFavorite:Number(next)} : p) }))
    setPreview((p) => p?.id === prompt.id ? {...p,isFavorite:Number(next)} : p)
    const response = await fetch('/api/favorites', { method: 'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({promptId:prompt.id}) })
    if (!response.ok) return toast('Could not update favorites')
    toast(next ? 'Saved to Favorites' : 'Removed from Favorites')
    if (favorites && !next) setCatalog((data) => ({...data,prompts:data.prompts.filter((p)=>p.id!==prompt.id)}))
  }

  const cartPrompt = async (prompt: Prompt) => {
    const response = await fetch('/api/cart', { method: 'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({promptId:prompt.id}) })
    if (!response.ok) return toast('Could not add prompt')
    const cart = await response.json()
    setCatalog((data) => ({...data,cartCount:cart.count}))
    toast(`${prompt.price ? 'Added' : 'Free prompt added'} — ${prompt.title}`)
  }

  const heading = useMemo(() => favorites ? 'Your saved prompts' : free ? 'Free prompts' : category !== 'all' ? category : 'Built to get you there', [favorites,free,category])

  return <AppShell categories={catalog.categories} activeCategory={category} cartCount={catalog.cartCount} onCategory={chooseCategory} onSearch={revealSearch} onFavorites={() => {setFavorites(true);setFree(false);setCategory('all')}} onNotice={toast}>
    <main className="storefront">
      <div className="topbar">
        <div className="filter-row">
          <div className="model-tabs" role="tablist" aria-label="Filter by model">
            {models.map((name) => <button key={name} className={model === name ? 'is-active' : ''} onClick={() => {setModel(name);setFavorites(false)}}>{name === 'all' && <Icon name="grid" />}{name === 'all' ? 'All' : name}</button>)}
          </div>
          <div className="sort-tabs" aria-label="Sort prompts">
            {sorts.map((name) => <button key={name} className={sort === name ? 'is-active' : ''} onClick={() => setSort(name)}>{name[0].toUpperCase()+name.slice(1)}</button>)}
          </div>
          <button className="search-trigger" onClick={() => setSearchOpen(!searchOpen)} aria-label="Toggle search"><Icon name={searchOpen ? 'close' : 'search'} /></button>
        </div>
        <div className={`search-reveal ${searchOpen ? 'is-open' : ''}`}><Icon name="search" /><input ref={searchRef} value={term} onChange={(e)=>setTerm(e.target.value)} placeholder={'Search prompts — “portrait”, “poster”, “cold email”…'} aria-label="Search prompts" />{term && <button onClick={()=>setTerm('')}>Clear</button>}</div>
      </div>
      <section className="gallery-wrap" aria-busy={loading}>
        <div className="gallery-heading"><div><p className="eyebrow">Curated tools for curious people</p><h1>{heading}<span>.</span></h1></div><p>{catalog.prompts.length} prompts · ranked by real marketplace signals</p></div>
        {catalog.prompts.length ? <div className={`masonry ${loading ? 'is-loading' : ''}`}>{catalog.prompts.map((prompt) => <PromptCard key={prompt.id} prompt={prompt} onFavorite={favoritePrompt} onCart={cartPrompt} onPreview={setPreview} />)}</div> : <div className="empty-state"><Icon name="search" /><h2>Nothing here yet</h2><p>{favorites ? 'Save a prompt and it will wait for you here.' : 'Try another model, category, or search.'}</p><button className="button button--dark" onClick={()=>{setTerm('');setFavorites(false);setFree(false);setModel('all');setCategory('all')}}>Clear filters</button></div>}
      </section>
    </main>
    <PromptModal prompt={preview} onClose={()=>setPreview(null)} onCart={cartPrompt} onFavorite={favoritePrompt} />
    <Toast message={notice} />
  </AppShell>
}

import { createFileRoute } from '@tanstack/react-router'
import { AppShell } from '../components/AppShell'
import { Icon } from '../components/Icons'
import { getAnalyticsData } from '../server/marketplace.server'

export const Route = createFileRoute('/analytics')({loader:()=>getAnalyticsData(),component:AnalyticsPage})

function AnalyticsPage(){
  const data=Route.useLoaderData()
  const max=Math.max(...data.daily.map((d:any)=>d.revenue),1)
  return <AppShell><main className="analytics-page"><div className="analytics-head"><div><p className="eyebrow">Creator command center</p><h1>Marketplace pulse<span>.</span></h1><p>Revenue, conversion, and category demand — calculated from local order data.</p></div><button className="button button--lime">Publish a prompt <Icon name="arrow"/></button></div>
    <section className="metrics"><Metric label="Gross revenue" value={`$${data.overview.grossRevenue.toFixed(2)}`} change="+18.4%"/><Metric label="Paid orders" value={String(data.overview.orders)} change="+6 this week"/><Metric label="Average order" value={`$${data.overview.averageOrderValue.toFixed(2)}`} change="SQL-calculated"/><Metric label="Conversion" value={`${data.overview.conversionRate.toFixed(2)}%`} change="Across catalog"/></section>
    <section className="analytics-grid"><article className="panel sales-panel"><div className="panel-title"><div><p className="eyebrow">Daily sales</p><h2>Revenue trend</h2></div><span>Jul 01 — Jul 14</span></div><div className="chart-bars">{data.daily.map((d:any)=><div key={d.day}><span style={{height:`${Math.max(d.revenue/max*100,3)}%`}} title={`$${d.revenue}`} /><small>{d.day.slice(-2)}</small></div>)}</div></article>
      <article className="panel"><div className="panel-title"><div><p className="eyebrow">Leaderboard</p><h2>Top creators</h2></div></div><div className="data-list creators-list">{data.creators.slice(0,5).map((c:any,i:number)=><div key={c.id}><span className="rank">0{i+1}</span><strong>{c.name}<small>{c.prompts} prompt{c.prompts===1?'':'s'} · {c.conversionRate}% conv.</small></strong><b>${c.revenue.toFixed(2)}</b></div>)}</div></article>
      <article className="panel category-panel"><div className="panel-title"><div><p className="eyebrow">Demand</p><h2>Category revenue</h2></div></div><div className="data-list">{data.categories.map((c:any)=><div key={c.name}><strong>{c.name}<small>{c.prompts} prompts · {c.sales} orders</small></strong><b>${c.revenue.toFixed(2)}</b></div>)}</div></article>
      <article className="panel creator-note"><Icon name="spark"/><p className="eyebrow">Creator program</p><h2>You make the good stuff. Keep 85%.</h2><p>Publish once, earn on every sale, and use clear demand signals to decide what to make next.</p><button className="text-link">Read creator guide <Icon name="arrow"/></button></article>
    </section>
  </main></AppShell>
}

function Metric({label,value,change}:{label:string;value:string;change:string}){return <article><p>{label}</p><strong>{value}</strong><span>{change}</span></article>}

import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { useState } from 'react'
import { AppShell } from '../components/AppShell'
import { Icon } from '../components/Icons'
import { Toast } from '../components/Toast'
import { compact } from '../components/PromptModal'
import { getPromptData } from '../server/marketplace.server'

export const Route = createFileRoute('/prompts/$promptId')({
  loader: async ({ params }) => {
    const prompt = await getPromptData({ data: { slug: params.promptId } })
    if (!prompt) throw notFound()
    return prompt
  },
  component: PromptDetail,
})

function PromptDetail() {
  const prompt = Route.useLoaderData()
  const [favorite, setFavorite] = useState(Boolean(prompt.isFavorite))
  const [cartCount, setCartCount] = useState(0)
  const [notice,setNotice] = useState('')
  const toast = (s:string) => {setNotice(s);window.setTimeout(()=>setNotice(''),2200)}
  const add = async () => { const r=await fetch('/api/cart',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({promptId:prompt.id})}); const c=await r.json();setCartCount(c.count);toast(`Added — ${prompt.title}`) }
  const save = async () => {await fetch('/api/favorites',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({promptId:prompt.id})});setFavorite(!favorite);toast(!favorite?'Saved to Favorites':'Removed from Favorites')}
  return <AppShell cartCount={cartCount} onNotice={toast}>
    <main className="detail-page">
      <Link to="/" className="back-link">← Back to gallery</Link>
      <div className="detail-grid">
        <div className="detail-media" style={{'--ratio':prompt.aspect.replace('/',' / ')} as React.CSSProperties}><img src={prompt.imageUrl} alt={prompt.title}/><span>{prompt.model}</span></div>
        <article className="detail-copy"><p className="eyebrow">{prompt.category} · by {prompt.seller}</p><h1>{prompt.title}</h1><p className="lede">{prompt.description}</p>
          <div className="detail-stats"><div><strong>★ {prompt.rating.toFixed(1)}</strong><span>average rating</span></div><div><strong>{compact(prompt.sold)}</strong><span>prompt runs</span></div><div><strong>#{Math.max(1,Math.round(140-prompt.rankScore))}</strong><span>market rank</span></div></div>
          <div className="prompt-sample"><div><span>Prompt preview</span><span>Works with {prompt.model}</span></div><p>{prompt.promptText}</p><div className="prompt-fade">Full prompt unlocked after purchase</div></div>
          <div className="purchase-row"><button className="button button--lime" onClick={add}>{prompt.price ? `Add to Cart · $${prompt.price}` : 'Get this prompt · Free'} <Icon name="arrow" /></button><button className={`save-large ${favorite?'is-active':''}`} onClick={save}><Icon name="bookmark" />{favorite?'Saved':'Save'}</button></div>
          <p className="fine-print"><Icon name="check" /> Instant access · Lifetime updates · 7-day refund policy</p>
        </article>
      </div>
    </main><Toast message={notice}/>
  </AppShell>
}

